const collections = [
 {id:'committees',title:'Committees',word:'Collective minds.',image:'t_IcelandMoss.jpg',description:'People, purpose, and shared decisions.',count:'6 committees'},
 {id:'programs',title:'Program information',word:'Paths forward.',image:'t_WaterIcelandGlacier.jpg',description:'Curricula, handbooks, and learning goals.',count:'4 programs'},
 {id:'handbook',title:'Faculty handbook',word:'The essentials.',image:'t_GlassFrog.jpg',description:'Your guide to life in the department.',count:'5 resources'},
 {id:'rpt',title:'Review, promotion & tenure',word:'Your next chapter.',image:'t_GrandCanyon.jpg',description:'Guidance for every career milestone.',count:'4 resources'},
 {id:'seminars',title:'Seminars',word:'Ideas in motion.',image:'t_MontanaDock.jpg',description:'New perspectives. Good conversations.',count:'3 resources'},
 {id:'social',title:'Social & storytelling',word:'Worth sharing.',image:'t_MidnightSun.jpg',description:'Our science, out in the world.',count:'4 channels'}
];
const grid=document.querySelector('#resource-grid');
grid.innerHTML=collections.map(c=>`<button class="resource-card" data-collection="${c.id}" aria-expanded="false" aria-controls="collection-shelf"><span class="cover"><img src="images/${c.image}" alt="" loading="lazy"><span class="cover-index">B+G / 0${collections.indexOf(c)+1}</span><span class="cover-word">${c.word}</span><span class="expand-icon" aria-hidden="true">+</span></span><span class="card-title">${c.title}<span class="card-count">${c.count}</span></span><span class="card-description">${c.description}</span></button>`).join('');
const events=[{day:'07',weekday:'WED',type:'DEPARTMENT SEMINAR',title:'Reading the hidden genome',person:'Dr. Maya Chen · Westlake University',time:'12:00–1:00 PM',location:'Life Sciences 210',description:'An exploration of how long-read sequencing is changing our understanding of structural variation.'},{day:'09',weekday:'FRI',type:'CIPHER COFFEE HOUR',title:'Good coffee. Open questions.',person:'Hosted by the CIPHER community',time:'10:00–11:00 AM',location:'Commons lounge',description:'Bring a question, an idea, or just yourself for an informal conversation with colleagues.'},{day:'13',weekday:'TUE',type:'EVOLVE TALK',title:'Evolution at the edges',person:'Dr. Julian Rivera · Northbridge University',time:'3:30–4:30 PM',location:'Research Hall 102',description:'A conversation about adaptation, population genomics, and life in changing environments.'}];
function eventMarkup(e,i){return `<button class="event" data-event="${i}"><span class="date"><strong>${e.day}</strong><span>${e.weekday}</span></span><span><span class="event-type">${e.type}</span><span class="event-title">${e.title}</span><span class="event-meta">${e.time}<br>${e.location}</span></span></button>`}
document.querySelector('#event-list').innerHTML=events.map(eventMarkup).join('');
// Replace null URLs with the department's real folder/document links when ready.
const item=(name,meta,files,description='',url=null)=>({name,meta,files,description,url});
const content={
 committees:{intro:'Find your people. Get to the work.',groups:{
  'All committees':[],
  'Teaching & learning':[item('Graduate Studies','Chair · Dr. Elena Park',['Meeting agendas','Graduate policies','Admissions rubrics'],'Graduate curricula, admissions, and student progress.'),item('Undergraduate Curriculum','Chair · Dr. Marcus Reed',['Curriculum proposals','Learning outcomes','Meeting notes'],'Course development and the undergraduate learning experience.')],
  'People & culture':[item('Faculty Affairs','Chair · Dr. Priya Shah',['Faculty development','Mentoring resources','Meeting minutes'],'Support for faculty development and department life.'),item('Community & Belonging','Chair · Dr. Simone Brooks',['Community initiatives','Event planning','Meeting notes'],'Building a welcoming and connected department.')],
  'Research & strategy':[item('Research & Computing','Chair · Dr. Noah Kim',['Computing resources','Research priorities','Meeting minutes'],'Shared infrastructure and research opportunities.'),item('Seminar Committee','Chair · Dr. Avery Morgan',['Speaker nominations','Seminar planning','Hosting checklist'],'Bringing new ideas and speakers into our community.')]
 }},
 programs:{intro:'The essentials for every stage of study.',groups:{'All programs':[item('Undergraduate program','B.S. · Bioinformatics',['Curriculum overview','Student learning outcomes','Course catalog']),item('Master’s program','M.S. · Bioinformatics & Genomics',['Degree requirements','Curriculum overview','Student learning outcomes']),item('Graduate certificate','Certificate · Applied Genomics',['Course sequence','Admissions overview','Certificate outcomes']),item('Doctoral program','Ph.D. · Bioinformatics & Genomics',['Ph.D. handbook','Milestones & examinations','Curriculum & learning outcomes'])]}},
 handbook:{intro:'Policies and practical guidance, close at hand.',groups:{'All resources':[item('Department faculty handbook','Department reference',['Department organization','Teaching expectations','Service & governance']),item('Graduate School policies','Graduate advising',['Graduate handbook','Degree requirements','Student support']),item('Dissertation advisor training','Mentoring & supervision',['Advisor training course','Mentoring agreements','Research supervision']),item('Getting started','New faculty & staff',['Onboarding checklist','Campus services','Who to contact']),item('Teaching & advising','Classroom resources',['Academic calendar','Advising guide','Course planning'])]}},
 rpt:{intro:'A clearer path through review, promotion, and tenure.',groups:{'All resources':[item('Review & promotion guidelines','Start here',['Annual review guidance','Promotion guidelines','Tenure expectations']),item('Dossier preparation','Templates & formatting',['Dossier template','Formatting checklist','Example table of contents']),item('Evaluation criteria','Rubrics & metrics',['Teaching rubric','Research criteria','Service contributions']),item('Timelines & support','Plan your review',['Submission timeline','Mentor conversations','Review contacts'])]}},
 seminars:{intro:'Make space for the next big idea.',groups:{'All resources':[item('Seminar schedule','Fall 2026',['Upcoming speakers','Past seminars','Room information']),item('Meet a visiting speaker','Faculty & student sign-ups',['One-on-one meetings','Graduate student lunch','Dinner hosting']),item('Nominate a speaker','Bring a new voice to campus',['Speaker nomination form','Selection priorities','Host responsibilities'])]}},
 social:{intro:'Connect with the department. Share what you’re working on.',groups:{'All channels':[item('Instagram','From the lab & beyond',['Research snapshots','Community moments']),item('LinkedIn','Our professional community',['Faculty highlights','Alumni stories','Department news']),item('Facebook','Keep in touch',['Department updates','Events & announcements']),item('Share a story','Have something worth celebrating?',['Research publications','Awards & milestones','Student achievements'])]}}
};
content.committees.groups['All committees']=Object.entries(content.committees.groups).filter(([key])=>key!=='All committees').flatMap(([,items])=>items);
let activeCollection=null,activeGroup=null;
const dialog=document.querySelector('#detail-dialog'),dialogContent=document.querySelector('#dialog-content');
function showDialog(html){dialogContent.innerHTML=html;dialog.setAttribute('aria-labelledby','dialog-title');if(!dialog.open)dialog.showModal()}
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function placeShelf(){const shelf=document.querySelector('#collection-shelf');if(!shelf)return;const cards=[...grid.querySelectorAll('.resource-card')];const columns=getComputedStyle(grid).gridTemplateColumns.split(' ').length;const index=cards.findIndex(c=>c.dataset.collection===activeCollection);cards[Math.min(cards.length-1,Math.floor(index/columns)*columns+columns-1)].after(shelf)}
function closeShelf(focus=true){document.querySelector('#collection-shelf')?.remove();const trigger=grid.querySelector('[aria-expanded=true]');trigger?.setAttribute('aria-expanded','false');if(focus)trigger?.focus();activeCollection=null}
function openCollection(id){if(activeCollection===id){closeShelf();return}closeShelf(false);activeCollection=id;activeGroup=Object.keys(content[id].groups)[0];const collection=collections.find(c=>c.id===id);const trigger=grid.querySelector(`[data-collection="${id}"]`);trigger.setAttribute('aria-expanded','true');const shelf=document.createElement('section');shelf.className='shelf';shelf.id='collection-shelf';shelf.setAttribute('aria-label',collection.title);shelf.innerHTML=`<div class="shelf-head"><div><h3>${collection.title}</h3><p class="shelf-intro">${content[id].intro}</p></div><button class="close-shelf" aria-label="Close ${collection.title}">×</button></div><div class="group-tabs" role="tablist" aria-label="${collection.title} groups"></div><div class="folder-list" id="folder-panel" role="tabpanel" tabindex="0"></div><p class="shelf-foot">Sample resources · Department links will be added here.</p>`;grid.append(shelf);placeShelf();shelf.querySelector('.close-shelf').onclick=()=>closeShelf();renderGroups();shelf.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})}
function renderGroups(){const groups=Object.keys(content[activeCollection].groups);const tabs=document.querySelector('.group-tabs');tabs.innerHTML=groups.map((g,i)=>`<button class="group-tab" role="tab" id="group-${i}" aria-controls="folder-panel" aria-selected="${g===activeGroup}" tabindex="${g===activeGroup?0:-1}">${g}</button>`).join('');tabs.querySelectorAll('button').forEach((button,i)=>{button.onclick=()=>{activeGroup=groups[i];renderGroups();document.querySelector(`#group-${i}`).focus()};button.onkeydown=e=>{let next=i;if(e.key==='ArrowRight')next=(i+1)%groups.length;else if(e.key==='ArrowLeft')next=(i+groups.length-1)%groups.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=groups.length-1;else return;e.preventDefault();activeGroup=groups[next];renderGroups();document.querySelector(`#group-${next}`).focus()}});const panel=document.querySelector('#folder-panel');panel.setAttribute('aria-labelledby',`group-${groups.indexOf(activeGroup)}`);const items=content[activeCollection].groups[activeGroup];panel.innerHTML=items.map((f,i)=>`<button class="folder" data-folder="${i}"><span class="folder-icon" aria-hidden="true">▱</span><span><span class="folder-name">${f.name}</span><span class="folder-meta">${f.meta}</span></span><span class="folder-plus" aria-hidden="true">+</span></button>`).join('');panel.querySelectorAll('button').forEach((button,i)=>button.onclick=()=>openResource(items[i]))}
function openResource(resource){if(resource.name==='Share a story'){openSubmission('Story');return}if(resource.name==='Seminar schedule'){openCalendar('Seminars');return}showDialog(`<p class="dialog-eyebrow">${collections.find(c=>c.id===activeCollection).title}</p><h2 id="dialog-title">${resource.name}</h2><p>${resource.meta}</p>${resource.description?`<p>${resource.description}</p>`:''}<ul class="dialog-resources">${resource.files.map(f=>`<li>▱ &nbsp; ${f}</li>`).join('')}</ul>${resource.url?`<a class="action" href="${resource.url}" target="_blank" rel="noopener noreferrer">Open department folder</a>`:'<p class="dialog-note">This is a sample folder preview. In the finished hub, this resource will link directly to its department folder or document.</p>'}`)}
grid.addEventListener('click',e=>{const card=e.target.closest('.resource-card');if(card)openCollection(card.dataset.collection)});
window.addEventListener('resize',placeShelf);
grid.addEventListener('keydown',e=>{if(e.key==='Escape'&&activeCollection)closeShelf()});
function showEvent(index){const event=events[index];showDialog(`<p class="dialog-eyebrow">${event.type}</p><h2 id="dialog-title">${event.title}</h2><p><strong>October ${Number(event.day)}, 2026 · ${event.time}</strong><br>${event.location}</p><p>${event.person}</p><p>${event.description}</p><p class="dialog-note">Illustrative event for this design preview. The live calendar will supply the title, speaker, time, and location.</p>`)}
document.addEventListener('click',e=>{const event=e.target.closest('[data-event]');if(event)showEvent(Number(event.dataset.event))});
function openCalendar(filter='All events'){showDialog(`<p class="dialog-eyebrow">DEPARTMENT CALENDAR · SAMPLE EVENTS</p><h2 id="dialog-title">October 2026</h2><div class="dialog-tabs"><button class="group-tab" id="all-events" aria-pressed="${filter==='All events'}">All events</button><button class="group-tab" id="seminar-events" aria-pressed="${filter==='Seminars'}">Seminars</button></div><div class="month-list">${events.map((e,i)=>filter==='All events'||e.type.includes('SEMINAR')?eventMarkup(e,i):'').join('')}</div><p class="dialog-note">Ready for a departmental calendar. A Google Calendar, Outlook calendar, or published calendar feed can replace these sample events when connected.</p>`);document.querySelector('#all-events').onclick=()=>openCalendar('All events');document.querySelector('#seminar-events').onclick=()=>openCalendar('Seminars')}
document.querySelector('#calendar-button').onclick=()=>openCalendar();
function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function openSubmission(type='Event'){showDialog(`<p class="dialog-eyebrow">CONTRIBUTE TO THE COMMONS</p><h2 id="dialog-title">Something worth sharing.</h2><p>Preview an event or story submission. Nothing is sent in this design prototype.</p><form id="submission-form" class="form-grid"><label>I'd like to share<select name="type"><option ${type==='Event'?'selected':''}>Event</option><option ${type==='Story'?'selected':''}>Story</option></select></label><label>Title<input name="title" required maxlength="150" placeholder="A seminar, a publication, a milestone…"></label><label>Your name<input name="name" required maxlength="100" autocomplete="name"></label><label>Details<textarea name="details" required maxlength="2000" placeholder="Tell us a little about it."></textarea></label><button class="action" type="submit">Preview submission</button></form>`);document.querySelector('#submission-form').onsubmit=e=>{e.preventDefault();const values=new FormData(e.target);showDialog(`<p class="dialog-eyebrow">${escapeHTML(values.get('type'))} · SUBMISSION PREVIEW</p><h2 id="dialog-title">${escapeHTML(values.get('title'))}</h2><p>From ${escapeHTML(values.get('name'))}</p><p style="white-space:pre-wrap">${escapeHTML(values.get('details'))}</p><div class="success">Your preview is ready. Nothing has been submitted or saved. The final form can send requests to the department team.</div>`)}}
document.querySelector('#share-button').onclick=()=>openSubmission();
